"""SSZ merkleization primitives (M3): zero_hash table, incremental
merkle-stack accumulator, and mix_in_length.

Implements docs/design/003-ssz-verifier.md §5.5. These are the building
blocks needed to merkleize a chunk stream (e.g. M1's 512-pubkey
`SyncCommittee` install-time check, design doc §2.7) without ever buffering
a full leaf layer, which is impossible above 128 leaves on the AVM (§2.8:
16,384 bytes for a 512-leaf layer exceeds the 4,096-byte AVM value cap).
"""
import typing

from algopy import Bytes, UInt64, subroutine, urange, op

# ---------------------------------------------------------------------------
# zero_hash: precomputed table, NOT on-demand recomputation.
#
# Design doc §5.5 / checklist item 6: on-demand recomputation of
# zero_hash(i) = sha256(zero_hash(i-1) || zero_hash(i-1)) measured at 67.5
# budget per level (§2.7); a table lookup is a few opcodes. This table holds
# the first 64 values (depths 0..63) as program constants -- 64 * 32 = 2,048
# program bytes, affordable within the 8,192-byte cap (§5.5) -- which is far
# beyond any real SSZ depth this project needs (the deepest published gindex
# is 221184, depth 17; the deepest single-app-call-safe depth is 10, §2.6).
#
# Kept as a plain `str` module constant (Puya only allows literal int/str/
# bytes at module scope, not constructed `algopy` values) and turned into a
# `Bytes` program constant inside `zero_hash` itself via `Bytes.from_hex`,
# which Puya folds to a single pushbytes -- there is no per-call hex-decode
# at runtime.
#
# _ZERO_HASH_TABLE_HEX, decoded, is _ZERO_HASH_TABLE[32*i : 32*i+32] ==
# zero_hash(i) for i in 0..63. Generated by: zh[0] = 32 zero bytes;
# zh[i] = sha256(zh[i-1] + zh[i-1]).
_ZERO_HASH_TABLE_HEX: typing.Final[str] = (
    ""
)

_ZERO_HASH_TABLE_DEPTH = 64


@subroutine
def zero_hash(depth: UInt64) -> Bytes:
    """Root of an all-zero subtree of the given depth.

    `zero_hash(0)` is 32 zero bytes. `zero_hash(i) = sha256(zero_hash(i-1) ||
    zero_hash(i-1))`. This is a table lookup into the precomputed
    `_ZERO_HASH_TABLE_HEX` program constant, not a recomputation -- see the
    module docstring above for why that distinction is load-bearing, not
    stylistic.
    """
    assert depth < _ZERO_HASH_TABLE_DEPTH, "zero_hash: depth exceeds precomputed table size (64)"
    table = Bytes.from_hex(_ZERO_HASH_TABLE_HEX)
    offset = depth * 32
    return table[offset : offset + 32]


@subroutine
def merkleize_stack_push(state: Bytes, filled: UInt64, chunk: Bytes) -> tuple[Bytes, UInt64]:
    """Push one 32-byte chunk into an incremental-merkleization accumulator.

    `state` is a packed stack of up to `depth+1` 32-byte nodes (caller must
    pre-size it to `32 * (depth + 1)` bytes, e.g. 320 bytes / 10 slots for a
    512-leaf tree); `filled` is a bitmask of which stack levels currently
    hold a carried partial node. This is the standard incremental/streaming
    binary-counter merkle accumulator (the same shape as the Ethereum
    deposit contract's incremental Merkle tree): pushing behaves like a
    binary counter increment, carrying (combining via `sha256`) through
    every currently-occupied level until it reaches an empty one. After `n`
    sequential pushes from an empty state, `filled` equals the binary
    representation of `n`.

    MUST be used instead of buffering a layer -- a full 512-leaf layer is
    16,384 bytes and exceeds the AVM's 4,096-byte value cap (design doc
    §2.8). Scratch requirement is `depth+1` slots of 32 bytes.

    Call `merkleize_stack_finalize` once all chunks are pushed to combine
    the accumulator into the root of a subtree of a chosen target depth,
    padding any never-filled level with `zero_hash(level)` -- never with 32
    zero bytes at every level (design doc §7.4: padding a level-i gap with
    `zero_hash(0)` instead of `zero_hash(i)` silently yields a wrong root,
    and this bug is invisible whenever the chunk count is a power of two).

    Returns the updated `(state, filled)`.
    """
    node = chunk
    level = UInt64(0)
    f = filled
    while op.getbit(f, level):
        sibling_offset = level * 32
        sibling = state[sibling_offset : sibling_offset + 32]
        node = op.sha256(sibling + node)
        f = f ^ (UInt64(1) << level)
        level += 1

    write_offset = level * 32
    assert write_offset + 32 <= state.length, "merkleize_stack_push: state too small for this many chunks"
    new_state = state[0:write_offset] + node + state[write_offset + 32 : state.length]
    new_filled = f | (UInt64(1) << level)
    return new_state, new_filled


@subroutine
def merkleize_stack_finalize(state: Bytes, filled: UInt64, depth: UInt64) -> Bytes:
    """Combine a `merkleize_stack_push` accumulator into the root of a
    subtree of the given target `depth` (`ceil(log2(N))` for `N` chunks).

    Every level that was never filled (i.e. every push chain that never
    grew that tall) is padded with `zero_hash(level)`, matching SSZ's
    zero-padding rule for non-power-of-two lengths (design doc §7.4). This
    is the same algorithm as the Ethereum deposit contract's `get_root`,
    generalized to an arbitrary `depth` and an explicit `filled` bitmask in
    place of a running deposit count (the two coincide for sequential
    pushes from empty, see `merkleize_stack_push`).

    Not itself named in design doc §5.5's three-subroutine list, but
    required to turn `merkleize_stack_push` into a usable end-to-end
    merkleization primitive -- `zero_hash` and `merkleize_stack_push` alone
    only build the accumulator, they never close it out into a single root.

    `depth == 0` is a special case, analogous to `compute_merkle_branch_root`'s
    own depth-0 convention (design doc §7.1): a depth-0 subtree has exactly
    one leaf slot, so its "root" IS that leaf (`state[0]`) if one was pushed,
    or `zero_hash(0)` if none was. The general loop below runs zero
    iterations at depth 0 and would otherwise always return `zero_hash(0)`
    regardless of `filled`, silently discarding a real pushed chunk.
    """
    if depth == 0:
        if op.getbit(filled, UInt64(0)):
            return state[0:32]
        return zero_hash(UInt64(0))

    node = zero_hash(UInt64(0))
    for level in urange(depth):
        if op.getbit(filled, level):
            sibling_offset = level * 32
            sibling = state[sibling_offset : sibling_offset + 32]
            node = op.sha256(sibling + node)
        else:
            node = op.sha256(node + zero_hash(level))
    return node


@subroutine
def mix_in_length(root: Bytes, length: UInt64) -> Bytes:
    """`sha256(root || uint256_le(length))` -- the SSZ `List`/`Bitlist` tail.

    `hash_tree_root` of an SSZ `List`/`Bitlist` mixes the runtime length
    into the merkleized-and-padded-to-type-limit root (design doc §2.11,
    §7.4-item-3): the tree itself must be sized from the type limit `N`,
    NOT the runtime length -- using the runtime length to size the tree is
    a classic SSZ bug that yields wrong roots for every non-full list.

    `length` must be encoded 32-byte LITTLE-endian. `op.itob` produces
    8-byte BIG-endian, so it is byte-reversed here and right-padded with 24
    zero bytes. Getting this endianness wrong yields a wrong root at
    identical budget (§2.11) -- it will never show up as a cost regression.
    """
    length_be = op.itob(length)
    length_le = Bytes()
    for one_byte in reversed(length_be):
        length_le += one_byte
    length_le_32 = length_le + op.Global.zero_address.bytes[0:24]
    return op.sha256(root + length_le_32)
